def _directories(params: Mapping[str, Any]) -> list[str]:
    found: list[str] = []
    declared = params.get("local_storage_path") or params.get("leveldb_path")
    if declared:
        found.append(str(declared))
    for raw in params.get("local_storage_paths") or []:
        text = str(raw)
        if text.endswith(".log") or text.endswith(".ldb"):
            text = text.rsplit("/", 1)[0]
        found.append(text)
    found.extend(PROFILE_DIRS)
    unique: list[str] = []
    for item in found:
        if item and item not in unique:
            unique.append(item)
    return unique


def read_opennote_state(context: Mapping[str, Any], params: Mapping[str, Any]) -> dict[str, Any]:
    """Return the OpenNote document, or an empty mapping when none is stored."""
